const input = $input.first().json;
const allowed = new Set(["project-management/project-management-studio-producer.md", "product/product-manager.md", "design/design-ux-researcher.md", "specialized/business-strategist.md", "product/product-behavioral-nudge-engine.md", "marketing/marketing-content-creator.md", "design/design-ux-architect.md", "design/design-brand-guardian.md", "design/design-visual-storyteller.md", "design/design-persona-walkthrough.md", "testing/testing-reality-checker.md"]);
const required = ['stage_id', 'logical_role', 'agent_path', 'task', 'project_context', 'working_document'];
const missing = required.filter(k => input[k] === undefined || input[k] === null);
if (missing.length) throw new Error(`Missing required fields: ${missing.join(', ')}`);
if (!allowed.has(input.agent_path)) throw new Error(`Agent path not allowlisted: ${input.agent_path}`);
if (input.agent_path.includes('..') || input.agent_path.startsWith('/')) throw new Error('Unsafe agent path');

return [{
  json: {
    ...input,
    source_ref: input.source_ref || '1c9bee5e6a3557355820726b1dc4e2549d566654',
    model: input.model || 'openrouter/free',
    temperature: Number.isFinite(Number(input.temperature)) ? Number(input.temperature) : 0.2,
    max_tokens: Number.isFinite(Number(input.max_tokens)) ? Number(input.max_tokens) : 5000,
    run_id: input.run_id || `aquapilot-${Date.now()}`,
    prompt_url: `https://raw.githubusercontent.com/CyberG3niusIT/agency-agents/${input.source_ref || '1c9bee5e6a3557355820726b1dc4e2549d566654'}/${input.agent_path}`
  }
}];

const prepared = $('Validate & Prepare').item.json;
const response = $input.first().json;
const content = response?.choices?.[0]?.message?.content;
if (!content) throw new Error('OpenRouter returned no message content');

let parsed;
try {
  parsed = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  parsed = { raw_output: content, parse_error: e.message };
}

const working = structuredClone(prepared.working_document || {});
working.stages = working.stages || {};
working.stages[prepared.stage_id] = {
  logical_role: prepared.logical_role,
  agent_path: prepared.agent_path,
  result: parsed,
  model_requested: prepared.model,
  model_used: response.model || null
};

return [{
  json: {
    ...prepared,
    working_document: working,
    latest_output: parsed,
    model_used: response.model || null
  }
}];
